/* Card set: Castles & Fortresses (generated from the approved roster-final.csv by the Castles build, schema per tools/csv-to-set.js).
   (castles-fortresses.js exceeds the comfortable push size, so the remaining cards live in
   castles-fortresses-additions.js, which must stay directly after 'castles-fortresses.js' in sets/manifest.js.) */
CardSets.register({"id":"castles-fortresses","name":"Castles & Fortresses","code":"CASTLE","description":"390 cards of the world's great strongholds — castles, fortified palaces, star forts, siege sites, and the keeps, moats and murder holes that defended them.","theme":{"primary":"#3d4457","secondary":"#b08d3c","artBackground":"#ece7dc","artFit":"cover"},"pack":{"name":"Castle Pack","emblem":"🏰","skin":"castles"},"cards":[{"name":"Carcassonne","rarity":"chase","id":"carcassonne","subtitle":"Fortress","details":"A double-walled medieval citadel in southern France, restored in the 19th century and ringed by 52 towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_carcassonne_aerial_2016.jpg?width=1024"},{"name":"Edinburgh Castle","rarity":"chase","id":"edinburgh-castle","subtitle":"Castle","details":"Built atop Castle Rock, an extinct volcano, it has guarded Scotland's capital since the 12th century and holds the Honours of Scotland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh_Castle_from_Esplanade_20211019.jpg?width=1024"},{"name":"Himeji Castle","rarity":"chase","id":"himeji-castle","subtitle":"Castle","details":"Japan's finest surviving feudal castle, a white hilltop complex of 83 buildings completed in its present form in 1609.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himeji_castle_in_may_2015.jpg?width=1024"},{"name":"Hohenzollern Castle","rarity":"chase","id":"hohenzollern-castle","subtitle":"Castle","details":"Ancestral seat of the Hohenzollern dynasty, this mountaintop castle was rebuilt in ornate Gothic Revival style in the 19th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Hohenzollern_10-2016.jpg?width=1024"},{"name":"Krak des Chevaliers","rarity":"chase","id":"krak-des-chevaliers","subtitle":"Castle","details":"A Crusader castle in Syria built by the Knights Hospitaller, ringed by concentric walls and a rock-cut moat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KRAK_DES_CHEVALIERS_-_GAR_-_6-00.jpg?width=1024"},{"name":"Malbork Castle","rarity":"chase","id":"malbork-castle","subtitle":"Castle","details":"Built by the Teutonic Order in Prussia, this vast brick castle on the Nogat River is the largest castle in the world by land area.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zesp%C3%B3%C5%82_Zamku_Krzy%C5%BCackiego_MALBORK_01.jpg?width=1024"},{"name":"Mont-Saint-Michel","rarity":"chase","id":"mont-saint-michel","subtitle":"Fortress","details":"A fortified island abbey off Normandy, cut off at high tide and crowned by a soaring Gothic monastery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mont-Saint-Michel_vu_du_ciel.jpg?width=1024"},{"name":"Neuschwanstein Castle","rarity":"chase","id":"neuschwanstein-castle","subtitle":"Castle","details":"Begun for Ludwig II of Bavaria in 1869, this romantic hilltop castle was modelled on medieval legend and the operas of Wagner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Neuschwanstein_2013.jpg?width=1024"},{"name":"Tower of London","rarity":"chase","id":"tower-of-london","subtitle":"Fortress","details":"William the Conqueror's White Tower rose in 1078; the fortress has served as palace, prison and treasury, and guards the Crown Jewels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tower_of_London_from_the_Shard_%288515883950%29.jpg?width=1024"},{"name":"Windsor Castle","rarity":"chase","id":"windsor-castle","subtitle":"Castle","details":"Founded by William the Conqueror around 1070, Windsor is the largest inhabited castle in the world and a working royal residence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Windsor_Castle_at_Sunset_-_Nov_2006.jpg?width=1024"},{"name":"Alcázar of Segovia","rarity":"legendary","id":"alcazar-of-segovia","subtitle":"Castle","details":"A ship-prowed fortress in Segovia that served as royal palace, prison and military academy across the centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Segovia_-_Alc%C3%A1zar_de_Segovia_22_2017-10-24.jpg?width=1024"},{"name":"Alhambra","rarity":"legendary","id":"alhambra","subtitle":"Palace","details":"A Nasrid palace-fortress in Granada famed for carved stucco, tilework, courtyards and the Court of the Lions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alhambra_evening_panorama_Mirador_San_Nicolas_sRGB-1.jpg?width=1024"},{"name":"Amer Fort","rarity":"legendary","id":"amer-fort","subtitle":"Fort","details":"A sandstone and marble fort-palace above Jaipur, reached by winding ramps built for elephants and royal processions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20191219_Fort_Amber%2C_Amer%2C_Jaipur_0955_9481.jpg?width=1024"},{"name":"Bran Castle","rarity":"legendary","id":"bran-castle","subtitle":"Castle","details":"This Transylvanian hilltop castle is linked in popular legend with Dracula, though its real history is as a royal residence and border stronghold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelul_Bran2.jpg?width=1024"},{"name":"Caernarfon Castle","rarity":"legendary","id":"caernarfon-castle","subtitle":"Castle","details":"Edward I began this mighty Welsh fortress in 1283; its polygonal towers were modelled on the walls of Constantinople.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caernarfon_Castle_1994.jpg?width=1024"},{"name":"Castel del Monte","rarity":"legendary","id":"castel-del-monte","subtitle":"Castle","details":"Frederick II built this Apulian hilltop castle in the 1240s as a precise octagon, with eight octagonal towers at its corners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castel_del_Monte_-_Andria.jpg?width=1024"},{"name":"Chillon Castle","rarity":"legendary","id":"chillon-castle","subtitle":"Castle","details":"An island castle on Lake Geneva near Montreux, Chillon was a Savoy stronghold guarding the route between the lake and Italy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/001_Chateau_de_Chillon_and_Dents_du_Midi_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Château de Chambord","rarity":"legendary","id":"chateau-de-chambord","subtitle":"Palace","details":"The largest Loire château, built for Francis I with a double-helix staircase and a forest of turrets and chimneys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Ch%C3%A2teau_de_Chambord_%28view_from_the_southeast%29.jpg?width=1024"},{"name":"Dover Castle","rarity":"legendary","id":"dover-castle","subtitle":"Castle","details":"Guarding the shortest sea crossing to France, Dover's great keep was built by Henry II in the 1180s above cliffs honeycombed with tunnels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_dover_castle_aerial_panorama_2017.jpg?width=1024"},{"name":"Eilean Donan","rarity":"legendary","id":"eilean-donan","subtitle":"Castle","details":"Standing where three sea lochs meet in the Highlands, Eilean Donan was rebuilt in the 20th century on the ruins of a 13th-century castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eilean_Donan_Castle%2C_Scotland_-_Jan_2011.jpg?width=1024"},{"name":"Eltz Castle","rarity":"legendary","id":"eltz-castle","subtitle":"Castle","details":"Tucked in a Moselle side valley, this turreted castle dates to the 12th century and has stayed with the same family ever since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wierschem%2C_Burg_Eltz%2C_2012-08_CN-01.jpg?width=1024"},{"name":"Forbidden City","rarity":"legendary","id":"forbidden-city","subtitle":"Palace","details":"Beijing's walled imperial palace complex, home to Ming and Qing emperors, protected by a wide moat and great gates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Forbidden_City_-_View_from_Coal_Hill.jpg?width=1024"},{"name":"Fort Sumter","rarity":"legendary","id":"fort-sumter","subtitle":"Fort","details":"Confederate guns fired on this Charleston Harbor sea fort in April 1861, opening the fighting of the American Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FortSumter2009.jpg?width=1024"},{"name":"Heidelberg Castle","rarity":"legendary","id":"heidelberg-castle","subtitle":"Castle","details":"Ruined by war and lightning, this red sandstone Renaissance castle above the Neckar became a symbol of German Romanticism.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heidelberg-2726936.jpg?width=1024"},{"name":"Hohensalzburg Fortress","rarity":"legendary","id":"hohensalzburg-fortress","subtitle":"Fortress","details":"One of Europe's largest medieval fortresses, it was begun in 1077 above Salzburg and expanded into a vast hilltop stronghold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salzburg_-_Festung_Hohensalzburg.JPG?width=1024"},{"name":"Keep","rarity":"legendary","id":"keep","subtitle":"Castle Part","details":"The keep was a castle's strongest tower and last refuge, housing the lord's hall, chambers and stores behind its thickest walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rochester_zamek_fc11_%28cropped%29.jpg?width=1024"},{"name":"Matsumoto Castle","rarity":"legendary","id":"matsumoto-castle","subtitle":"Castle","details":"A black-lacquered flatland castle in Nagano, whose five-storey wooden keep survives from the late 1500s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matsumoto_Castle_Keep_Tower.jpg?width=1024"},{"name":"Moscow Kremlin","rarity":"legendary","id":"moscow-kremlin","subtitle":"Fortress","details":"Moscow's fortified centre, its red-brick walls and towers enclose cathedrals, palaces and the seat of Russian government.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moscow_Kremlin_%288281675670%29.jpg?width=1024"},{"name":"Palace of Versailles","rarity":"legendary","id":"palace-of-versailles","subtitle":"Palace","details":"Louis XIV transformed a royal hunting lodge into France's seat of power, a vast palace ringed by formal gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palace_of_Versailles_-_garden_fa%C3%A7ade.jpg?width=1024"},{"name":"Pena Palace","rarity":"legendary","id":"pena-palace","subtitle":"Palace","details":"A Romanticist hilltop palace in Sintra painted in vivid red and yellow, built for Ferdinand II of Portugal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sintra_-_Palacio_da_Pena_%2820332995770%29.jpg?width=1024"},{"name":"Potala Palace","rarity":"legendary","id":"potala-palace","subtitle":"Palace","details":"A vast white-and-red palace fortress rising above Lhasa, built in the 1600s as the Dalai Lama's winter residence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potala_Palace_HQ.jpg?width=1024"},{"name":"Siege of Constantinople","rarity":"legendary","id":"siege-of-constantinople","subtitle":"Siege","details":"In 1453 Mehmed II's cannons breached Constantinople's Theodosian Walls, ending the Byzantine Empire after 53 days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Istanbul_asv2021-11_img65_Walls_of_Constantinople.jpg?width=1024"},{"name":"Stirling Castle","rarity":"legendary","id":"stirling-castle","subtitle":"Castle","details":"Perched on a volcanic crag above the Forth, Stirling controlled the gateway between Lowland and Highland Scotland for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stirling_Castle_Aerial_Photo.jpg?width=1024"},{"name":"The Alamo","rarity":"legendary","id":"the-alamo","subtitle":"Fort","details":"A Spanish mission turned fortress in San Antonio, defended in the famous 1836 siege during the Texas Revolution.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alamo_pano.jpg?width=1024"},{"name":"Topkapi Palace","rarity":"legendary","id":"topkapi-palace","subtitle":"Palace","details":"Istanbul's walled palace of Ottoman sultans for nearly four centuries, set behind gates and courtyards above the Bosphorus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Topkapi_Palace_Bosphorus_002.JPG?width=1024"},{"name":"Wartburg","rarity":"legendary","id":"wartburg","subtitle":"Castle","details":"Above Eisenach, this castle sheltered Martin Luther in 1521-22, where he translated the New Testament into German.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thuringia_Eisenach_asv2020-07_img23_Wartburg_Castle.jpg?width=1024"},{"name":"Wawel Castle","rarity":"legendary","id":"wawel-castle","subtitle":"Castle","details":"Crowning Wawel Hill above the Vistula in Kraków, this castle was the seat of Polish kings for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wawel_%284%29.jpg?width=1024"},{"name":"Agra Fort","rarity":"epic","id":"agra-fort","subtitle":"Fortress","details":"A walled Mughal palace city of red sandstone on the Yamuna, holding marble halls within a mile of ramparts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agra_03-2016_16_Agra_Fort.jpg?width=1024"},{"name":"Alcázar of Toledo","rarity":"epic","id":"alcazar-of-toledo","subtitle":"Fortress","details":"A stone fortress on Toledo's highest hill, rebuilt under Charles V and long used as a military academy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FP_Toledo_Alcazar_2025_-_Views.jpg?width=1024"},{"name":"Alnwick Castle","rarity":"epic","id":"alnwick-castle","subtitle":"Castle","details":"Home of the Dukes of Northumberland since 1309, Alnwick's vast bailey and keep stand guard near the Scottish border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alnwick_-_Alnwick_Castle_-_30.jpg?width=1024"},{"name":"Bamburgh Castle","rarity":"epic","id":"bamburgh-castle","subtitle":"Castle","details":"Rising 46 metres above the Northumberland coast, Bamburgh was the seat of Northumbrian kings before the Normans rebuilt it in stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh_Castle%2C_beautiful_day.jpg?width=1024"},{"name":"Beaumaris Castle","rarity":"epic","id":"beaumaris-castle","subtitle":"Castle","details":"Begun in 1295, Beaumaris on Anglesey is a near-perfect concentric design of walls within walls, though it was never finished.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castell_Beaumaris_Castle%2C_Ynys_Mon_%28Anglesey%29%2C_Wales_05.jpg?width=1024"},{"name":"Belém Tower","rarity":"epic","id":"belem-tower","subtitle":"Fortress","details":"A Manueline fortress in Lisbon built to guard the Tagus estuary and the route of Portugal's sea voyages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Torre_Bel%C3%A9m_April_2009-4a.jpg?width=1024"},{"name":"Blarney Castle","rarity":"epic","id":"blarney-castle","subtitle":"Castle","details":"Built by Cormac MacCarthy in 1446, this County Cork stronghold is famed for the Blarney Stone, said to grant the gift of eloquence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blarney_Castle_Ireland.jpg?width=1024"},{"name":"Burghausen Castle","rarity":"epic","id":"burghausen-castle","subtitle":"Castle","details":"Stretching over a kilometre along a ridge above the Salzach, Burghausen is among the longest castle complexes in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burghausen_-_Hauptburg_%281%29.JPG?width=1024"},{"name":"Castel Sant'Angelo","rarity":"epic","id":"castel-santangelo","subtitle":"Fortress","details":"Begun as Emperor Hadrian's mausoleum in Rome, this cylindrical fortress later served popes as a refuge linked to the Vatican by a walled passage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castel_Sant%27Angelo_at_Night.jpg?width=1024"},{"name":"Castillo San Felipe de Barajas","rarity":"epic","id":"castillo-san-felipe-de-barajas","subtitle":"Fortress","details":"Cartagena's great Spanish hilltop fortress, one of the largest colonial fortifications built in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/62_-_Carthag%C3%A8ne_-_D%C3%A9cembre_2008.jpg?width=1024"},{"name":"Château de Chenonceau","rarity":"epic","id":"chateau-de-chenonceau","subtitle":"Castle","details":"A Loire château built across the River Cher on a graceful arched bridge, shaped by a succession of women owners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chateau_de_Chenonceau_2008E_%28adjusted2%29.jpg?width=1024"},{"name":"Château de Pierrefonds","rarity":"epic","id":"chateau-de-pierrefonds","subtitle":"Castle","details":"A vast medieval fortress near Compiègne, rebuilt in the 19th century as an imperial residence in romantic style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_de_Pierrefonds_vu_depuis_le_Parc.jpg?width=1024"},{"name":"Conwy Castle","rarity":"epic","id":"conwy-castle","subtitle":"Castle","details":"Built by Edward I in just four years from 1283, Conwy's eight great towers form one of Europe's best-preserved medieval fortresses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conwy_Castle%2C_water_view1.jpg?width=1024"},{"name":"Corvin Castle","rarity":"epic","id":"corvin-castle","subtitle":"Castle","details":"One of Europe's largest castles, this Gothic-Renaissance stronghold in Hunedoara was built for John Hunyadi in 15th-century Transylvania.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hunedoara_castle.jpg?width=1024"},{"name":"Fenestrelle Fort","rarity":"epic","id":"fenestrelle-fort","subtitle":"Fortress","details":"Italy's great Alpine fortress climbs a mountainside in Piedmont with a covered stairway of some 4,000 steps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fenestrelle_-_Forte_di_Fenestrelle.jpeg?width=1024"},{"name":"Fort Boyard","rarity":"epic","id":"fort-boyard","subtitle":"Fort","details":"A stone sea fort built on a shoal off western France, later famous worldwide as the setting of a television game show.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Boyard_en2013.jpg?width=1024"},{"name":"Fort Jefferson","rarity":"epic","id":"fort-jefferson","subtitle":"Fort","details":"A vast unfinished hexagonal sea fort of some 16 million bricks on Garden Key in Florida's Dry Tortugas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort-Jefferson_Dry-Tortugas.jpg?width=640"},{"name":"Fort Niagara","rarity":"epic","id":"fort-niagara","subtitle":"Fort","details":"Guarding the mouth of the Niagara River, its 1726 French Castle is the oldest building on the Great Lakes shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/French_castle_at_Fort_Niagara_2.JPG?width=1024"},{"name":"Gatehouse","rarity":"epic","id":"gatehouse","subtitle":"Castle Part","details":"The gatehouse guarded a castle's main entrance, often with twin towers, a portcullis, murder holes and guard rooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harlech_Castle%2C_The_entrance_gatehouse_-_geograph.org.uk_-_6138219.jpg?width=1024"},{"name":"Harlech Castle","rarity":"epic","id":"harlech-castle","subtitle":"Castle","details":"Edward I's concentric fortress at Harlech, built from 1283, clings to a rocky crag overlooking Tremadog Bay and Snowdonia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harlech_Castle%2C_Merionethshire%2C_Wales_-_25-06-2017.jpg?width=1024"},{"name":"Haut-Koenigsbourg","rarity":"epic","id":"haut-koenigsbourg","subtitle":"Castle","details":"A mountain stronghold above the Alsace plain, restored under Wilhelm II to its medieval appearance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_of_Haut-Koenigsbourg_%282%29.jpg?width=1024"},{"name":"Hochosterwitz Castle","rarity":"epic","id":"hochosterwitz-castle","subtitle":"Castle","details":"Perched on a dolomite rock in Carinthia, this castle is reached through 14 fortified gates built to resist Ottoman raids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St._Georgen_am_L%C3%A4ngsee_-_Burg_Hochosterwitz_%28b%29.JPG?width=1024"},{"name":"Hwaseong Fortress","rarity":"epic","id":"hwaseong-fortress","subtitle":"Fortress","details":"Suwon's late-1700s fortress walls stretch 3.5 miles around the old city, with floodgates, towers and command posts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hwaseong_Fortress%2C_Suwon%2C_Gyeonggi-do%2C_Republic_of_Korea_%282%29.jpg?width=1024"},{"name":"Karlštejn Castle","rarity":"epic","id":"karlstejn-castle","subtitle":"Castle","details":"Founded by Emperor Charles IV in 1348, this Gothic castle near Prague was built to guard the imperial crown jewels and relics.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Karlstein_-_Karl%C5%A1tejn_-_panoramio.jpg?width=1024"},{"name":"Kronborg","rarity":"epic","id":"kronborg","subtitle":"Castle","details":"This Danish Renaissance castle at Helsingør guards the Øresund strait and is famed as Elsinore, the setting of Shakespeare's Hamlet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kronborg_April_2026_10.jpg?width=1024"},{"name":"Kumamoto Castle","rarity":"epic","id":"kumamoto-castle","subtitle":"Castle","details":"A great black castle in Kyushu, famed for its curved stone walls designed to stop attackers from climbing them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kumamoto_Castle_Keep_Tower_20221022-3.jpg?width=1024"},{"name":"Königstein Fortress","rarity":"epic","id":"konigstein-fortress","subtitle":"Fortress","details":"A vast hilltop fortress above the Elbe in Saxony, Königstein served for centuries as a refuge, treasury and state prison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_photo_of_Festung_K%C3%B6nigstein%2C_October_2008.jpg?width=1024"},{"name":"Lichtenstein Castle","rarity":"epic","id":"lichtenstein-castle-wurttemberg","subtitle":"Castle","details":"Built in the 1840s on a cliff edge in the Swabian Alps, this small Gothic Revival castle was inspired by Wilhelm Hauff's novel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Lichtenstein_04-2010.jpg?width=1024"},{"name":"Louvre Palace","rarity":"epic","id":"louvre-palace","subtitle":"Palace","details":"Begun as a medieval fortress on the Seine, the Louvre grew into a royal palace and later a great museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/West_facade_of_the_Cour_Carr%C3%A9e%2C_Louvre_Palace%2C_Paris_5_October_2017.jpg?width=1024"},{"name":"Marksburg","rarity":"epic","id":"marksburg","subtitle":"Castle","details":"Above Braubach on the Rhine, the Marksburg is one of the few hill castles in the valley never to have been destroyed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marksburg-Braubach.jpg?width=1024"},{"name":"Masada","rarity":"epic","id":"masada","subtitle":"Fortress","details":"A Herodian palace fortress on a desert mesa above the Dead Sea, reached by a winding Snake Path and cable car.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Israel-2013-Aerial_21-Masada.jpg?width=640"},{"name":"Mehrangarh Fort","rarity":"epic","id":"mehrangarh-fort","subtitle":"Fort","details":"A towering fort above Jodhpur, its palaces enclosed by walls rising from a sheer rocky hill 400 feet high.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mehrangarh_Fort_sanhita.jpg?width=1024"},{"name":"Moat","rarity":"epic","id":"moat","subtitle":"Castle Part","details":"A moat was a deep ditch, dry or filled with water, dug around a castle to slow attackers and keep siege engines at a distance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beaumaris_Castle_-_geograph.org.uk_-_4393765.jpg?width=1024"},{"name":"Olavinlinna","rarity":"epic","id":"olavinlinna","subtitle":"Castle","details":"Founded in 1475 on a rocky islet in Finland's lake country, this three-towered castle guarded the eastern border of Swedish rule.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olavinlinna_Savonlinna_Finland.jpg?width=1024"},{"name":"Osaka Castle","rarity":"epic","id":"osaka-castle","subtitle":"Castle","details":"Rebuilt in concrete in 1931 on Toyotomi Hideyoshi's castle site, ringed by massive stone walls and moats in Osaka.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osaka_Castle_03bs3200.jpg?width=1024"},{"name":"Palmanova","rarity":"epic","id":"palmanova","subtitle":"Fortress","details":"A Venetian star-fort town founded in 1593, built as a perfect nine-pointed star of walls and bastions in Friuli.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cinta_muraria_di_Palmanova.jpg?width=1024"},{"name":"Papal Palace of Avignon","rarity":"epic","id":"papal-palace-of-avignon","subtitle":"Palace","details":"A vast Gothic palace in Avignon that housed popes in the 14th century, fortified like a citadel on its rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Avignon_Palais_des_Papes_2013.jpg?width=1024"},{"name":"Predjama Castle","rarity":"epic","id":"predjama-castle","subtitle":"Castle","details":"Built into the mouth of a huge cave in Slovenia, this Renaissance castle sits halfway up a 123-metre cliff face.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6hlenburg_Predjama_in_Slovenien.jpg?width=1024"},{"name":"Red Fort","rarity":"epic","id":"red-fort","subtitle":"Fortress","details":"Delhi's red sandstone imperial fortress, built for Shah Jahan in the 1640s behind walls stretching over a mile.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Delhi_fort.jpg?width=1024"},{"name":"Schwerin Palace","rarity":"epic","id":"schwerin-palace","subtitle":"Palace","details":"Set on an island in Lake Schwerin, this ornate 19th-century palace of turrets and gilding is nicknamed the Neuschwanstein of the North.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Schwerin_Castle_%28view_from_the_east%29.jpg?width=1024"},{"name":"Siege of Malta","rarity":"epic","id":"siege-of-malta","subtitle":"Siege","details":"In 1565 a small force of Knights Hospitaller and Maltese held Malta against a vast Ottoman armada, saving the island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malta_-_Valletta_-_Misrah_Sant%27_Iermu_-_Fort_St._Elmo_02_ies.jpg?width=1024"},{"name":"Siege of Orléans","rarity":"epic","id":"siege-of-orleans","subtitle":"Siege","details":"In 1429 Joan of Arc's arrival helped lift the English siege of Orléans, a turning point of the Hundred Years' War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Statue_%C3%A9questre_de_Jeanne_d%27Arc_%C3%A0_Orl%C3%A9ans_%28Place_du_Martroi%29.jpg?width=1024"},{"name":"Siege of Vienna","rarity":"epic","id":"siege-of-vienna","subtitle":"Siege","details":"In 1683 Ottoman forces besieged Vienna until a relief army descending from the Kahlenberg heights broke the siege lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%B6bling_%28Wien%29_-_Kahlenberg_%282%29.JPG?width=1024"},{"name":"Spiš Castle","rarity":"epic","id":"spis-castle","subtitle":"Castle","details":"One of Central Europe's largest castle complexes, these Slovak ruins spread over a travertine hill above Spišské Podhradie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20180503_Zamek_Spiski_2705_DxO.jpg?width=1024"},{"name":"St Michael's Mount","rarity":"epic","id":"st-michaels-mount","subtitle":"Fortress","details":"A tidal island off Cornwall crowned by a castle and church, St Michael's Mount is cut off from Marazion by the sea twice a day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St_Michael%27s_Mount_View.jpg?width=1024"},{"name":"Trakai Island Castle","rarity":"epic","id":"trakai-island-castle","subtitle":"Castle","details":"Built on an island in Lake Galvė by Lithuania's grand dukes, this red-brick Gothic castle was a major ducal stronghold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Traku_pilis_by_Augustas_Didzgalvis.jpg?width=1024"},{"name":"Warwick Castle","rarity":"epic","id":"warwick-castle","subtitle":"Castle","details":"Founded in 1068 beside the River Avon, Warwick grew from a Norman motte into a great fortress of the earls of Warwick.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warwick_Castle_May_2016.jpg?width=1024"},{"name":"Český Krumlov Castle","rarity":"epic","id":"cesky-krumlov-castle","subtitle":"Castle","details":"The second-largest castle complex in Czechia, it rises above the Vltava old town with a tall painted tower and a Baroque theatre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD_Krumlov%2C_z%C3%A1mek_cel%C3%BD_z_vyhl%C3%ADdky.jpg?width=1024"},{"name":"Arundel Castle","rarity":"rare","id":"arundel-castle","subtitle":"Castle","details":"Founded on Christmas Day 1067, Arundel in West Sussex has been the seat of the Dukes of Norfolk for over 850 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_castle_arundel_aerial_pano_2017.jpg?width=1024"},{"name":"Barbican","rarity":"rare","id":"barbican","subtitle":"Castle Part","details":"A barbican is a fortified outwork guarding a gate or bridge, forcing attackers into a narrow killing ground before the walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barbican%2C_Florian_Gate_and_Planty_Park%2C_Basztowa_Street%2C_Old_Town%2C_Krak%C3%B3w%2C_Poland.jpg?width=1024"},{"name":"Belgrade Fortress","rarity":"rare","id":"belgrade-fortress","subtitle":"Fortress","details":"Overlooking the meeting of the Sava and Danube in Kalemegdan Park, this fortress was rebuilt by Romans, Ottomans and Austrians alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/P037152-661920_-_Belgrade_fortress_stand_at_the_downtown_of_Belgrade.jpg?width=1024"},{"name":"Bodiam Castle","rarity":"rare","id":"bodiam-castle","subtitle":"Castle","details":"Built in 1385 amid fears of French invasion, Bodiam's moated towers and gatehouse are a classic picture of a late medieval castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bodiam-castle-10My8-1197.jpg?width=1024"},{"name":"Caerphilly Castle","rarity":"rare","id":"caerphilly-castle","subtitle":"Castle","details":"Wales's largest castle, built from 1268 by Gilbert de Clare, pioneered concentric defences and vast water barriers in Britain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caerphilly_aerial.jpg?width=1024"},{"name":"Cairo Citadel","rarity":"rare","id":"cairo-citadel","subtitle":"Fortress","details":"Saladin's hilltop citadel in Cairo, seat of Egypt's rulers for centuries, later crowned by the Mosque of Muhammad Ali.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_HuTect_ShOts_-_Citadel_of_Salah_El.Din_and_Masjid_Muhammad_Ali_%D9%82%D9%84%D8%B9%D8%A9_%D8%B5%D9%84%D8%A7%D8%AD_%D8%A7%D9%84%D8%AF%D9%8A%D9%86_%D8%A7%D9%84%D8%A3%D9%8A%D9%88%D8%A8%D9%8A_%D9%88%D9%85%D8%B3%D8%AC%D8%AF_%D9%85%D8%AD%D9%85%D8%AF_%D8%B9%D9%84%D9%8A_-_Cairo_-_Egypt_-_17_04_2010_%284%29.jpg?width=1024"},{"name":"Cardiff Castle","rarity":"rare","id":"cardiff-castle","subtitle":"Castle","details":"Cardiff Castle layers a Norman keep on Roman walls with a Victorian Gothic palace created for the Marquess of Bute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_Cardiff_Castle.jpg?width=1024"},{"name":"Charlottenburg Palace","rarity":"rare","id":"charlottenburg-palace","subtitle":"Palace","details":"Berlin's largest palace began in 1695 as a summer residence for Sophie Charlotte, the first queen consort in Prussia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Schloss_Charlottenburg_%28view_from_the_southwest%29.jpg?width=1024"},{"name":"Chittorgarh Fort","rarity":"rare","id":"chittorgarh-fort","subtitle":"Fortress","details":"Rajasthan's largest fort, a vast hilltop stronghold of Mewar remembered for sieges by Alauddin Khalji and Akbar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chittorgarh_fort.JPG?width=1024"},{"name":"Château d'Amboise","rarity":"rare","id":"chateau-d-amboise","subtitle":"Castle","details":"A royal Loire château above Amboise where Leonardo da Vinci spent his final years at nearby Clos Lucé.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_et_tour_des_Minimes_%28Amboise%29.jpg?width=1024"},{"name":"Château d'Azay-le-Rideau","rarity":"rare","id":"chateau-d-azay-le-rideau","subtitle":"Castle","details":"A graceful Renaissance château set on an island in the Indre, its facade reflected in the surrounding water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chateau-Azay-le-Rudeau-1.jpg?width=1024"},{"name":"Château de Beynac","rarity":"rare","id":"chateau-de-beynac","subtitle":"Castle","details":"A cliff-top Dordogne castle once held by Richard the Lionheart, staring across the river at rival Castelnaud.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_of_Beynac_27.jpg?width=1024"},{"name":"Château de Bonaguil","rarity":"rare","id":"chateau-de-bonaguil","subtitle":"Castle","details":"A late-medieval fortress in the Lot-et-Garonne packed with towers, built to withstand artillery yet never besieged.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bonaguil.jpg?width=1024"},{"name":"Château de Castelnaud","rarity":"rare","id":"chateau-de-castelnaud","subtitle":"Castle","details":"A Dordogne stronghold facing its rival Beynac across the river, now home to a museum of medieval warfare.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_of_Castelnaud_25.jpg?width=1024"},{"name":"Château de Chinon","rarity":"rare","id":"chateau-de-chinon","subtitle":"Castle","details":"A sprawling royal fortress above the Vienne where Joan of Arc first met the future Charles VII in 1429.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinon_-_Ch%C3%A2teau_vu_depuis_la_plage.jpg?width=1024"},{"name":"Château de Saumur","rarity":"rare","id":"chateau-de-saumur","subtitle":"Castle","details":"A white-stone fortress above the Loire that served counts, kings and armies, and later housed cavalry schools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_de_Saumur_2008_PD_10.JPG?width=1024"},{"name":"Château de Villandry","rarity":"rare","id":"chateau-de-villandry","subtitle":"Castle","details":"A Renaissance Loire château famed above all for its recreated ornamental and kitchen gardens in geometric parterres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_de_Villandry._France.jpg?width=1024"},{"name":"Citadel of Aleppo","rarity":"rare","id":"citadel-of-aleppo","subtitle":"Fortress","details":"A fortified palace mound in Aleppo occupied since antiquity, crowned by medieval walls, gates and a great hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Citadel_of_Aleppo.jpg?width=1024"},{"name":"Citadel of Besançon","rarity":"rare","id":"citadel-of-besancon","subtitle":"Fortress","details":"Vauban's great citadel crowns a rocky loop of the River Doubs above the old town of Besançon in eastern France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_the_Citadel_of_Besan%C3%A7on_%28view_from_the_southwest%29.jpg?width=1024"},{"name":"Coca Castle","rarity":"rare","id":"coca-castle","subtitle":"Castle","details":"A 15th-century Castilian castle built largely of brick in Mudéjar style, ringed by a deep dry moat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_Coca%2C_Segovia.jpg?width=1024"},{"name":"Colditz Castle","rarity":"rare","id":"colditz-castle","subtitle":"Castle","details":"A Renaissance castle in Saxony that became the Oflag IV-C prisoner-of-war camp, famed for its prisoners' escape attempts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colditz_Castle_2011_b_%28cropped%29.jpg?width=1024"},{"name":"Drawbridge","rarity":"rare","id":"drawbridge","subtitle":"Castle Part","details":"A drawbridge spans a moat on hinges and chains, raised to seal the gate or lowered to let friends cross into the castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cawdor_Castle%2C_Drawbridge_-_geograph.org.uk_-_2346095.jpg?width=1024"},{"name":"Dunluce Castle","rarity":"rare","id":"dunluce-castle","subtitle":"Castle","details":"Dunluce clings to basalt cliffs on the Antrim coast; part of it collapsed into the sea during a storm in 1639.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dunluce_Castle_Northern_Ireland_1.jpg?width=1024"},{"name":"Dunnottar Castle","rarity":"rare","id":"dunnottar-castle","subtitle":"Castle","details":"This cliff-top ruin near Stonehaven once hid the Honours of Scotland from Oliver Cromwell's invading army in 1651.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dunnottar_Castle_-_geograph.org.uk_-_8057610.jpg?width=640"},{"name":"Ehrenbreitstein Fortress","rarity":"rare","id":"ehrenbreitstein-fortress","subtitle":"Fortress","details":"High above the Rhine confluence at Koblenz, this 19th-century fortress was among the largest in Europe when completed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Festung_Ehrenbreitstein_Luftbild_080.jpg?width=1024"},{"name":"Elmina Castle","rarity":"rare","id":"elmina-castle","subtitle":"Castle","details":"Built by the Portuguese in 1482 on Ghana's coast, the oldest European building in sub-Saharan Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elmina_Castle_-_Ghana.jpg?width=1024"},{"name":"Fort Bard","rarity":"rare","id":"fort-bard","subtitle":"Fort","details":"This Piedmont cliff fort blocks the Aosta Valley; Napoleon besieged it in 1800, then ordered it destroyed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Forte_di_Bard_in_2026.jpg?width=1024"},{"name":"Fort George","rarity":"rare","id":"fort-george-scotland","subtitle":"Fort","details":"Built after the Jacobite rising of 1745 near Inverness, this vast artillery fort has remained a working garrison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_George_-_geograph.org.uk_-_1242152.jpg?width=1024"},{"name":"Fort Laramie","rarity":"rare","id":"fort-laramie","subtitle":"Fort","details":"A Wyoming trading post turned army fort that guarded emigrant trails and hosted key treaty councils with Plains tribes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Laramie_-_Wyoming_-_14322716998.jpg?width=1024"},{"name":"Fort Point","rarity":"rare","id":"fort-point","subtitle":"Fort","details":"A Civil War-era brick fort tucked beneath the southern end of San Francisco's Golden Gate Bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Point%2C_September_2019-8795.jpg?width=1024"},{"name":"Fort Pulaski","rarity":"rare","id":"fort-pulaski","subtitle":"Fort","details":"Union rifled cannon breached its thick brick walls in 1862, proving masonry forts could not withstand modern artillery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FtPulaskiInside.jpg?width=1024"},{"name":"Fortaleza Ozama","rarity":"rare","id":"fortaleza-ozama","subtitle":"Fortress","details":"Raised in Santo Domingo from 1502, it is regarded as the oldest European military fortification in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Santo_Domingo_-_Fortaleza_Ozama_0805.JPG?width=1024"},{"name":"Frederiksborg Castle","rarity":"rare","id":"frederiksborg-castle","subtitle":"Palace","details":"Denmark's largest Renaissance palace, built for Christian IV on three islets in Hillerød's castle lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg_Castle_and_boat_crop.jpg?width=1024"},{"name":"Golubac Fortress","rarity":"rare","id":"golubac-fortress","subtitle":"Fortress","details":"This medieval Serbian fortress guards the Iron Gates gorge of the Danube, its nine towers rising straight from the river cliffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golubac_Fortress_01.jpg?width=1024"},{"name":"Gravensteen","rarity":"rare","id":"gravensteen","subtitle":"Castle","details":"Ghent's Castle of the Counts, built in 1180, is a moated stone stronghold modelled on crusader castles the count saw in the Holy Land.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gent_Gravensteen_R01.jpg?width=1024"},{"name":"Great Hall","rarity":"rare","id":"great-hall","subtitle":"Castle Part","details":"The great hall was a castle's social heart, where the household feasted, held court and received guests beneath tall windows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/STIRLING_CASTLE_Great_Hall_interior_view.JPG?width=1024"},{"name":"Great Siege of Gibraltar","rarity":"rare","id":"great-siege-of-gibraltar","subtitle":"Siege","details":"From 1779 to 1783 Spain and France besieged Gibraltar; the garrison held out and miners cut galleries into the Rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great_Siege_Tunnels.jpg?width=1024"},{"name":"Guimarães Castle","rarity":"rare","id":"guimaraes-castle","subtitle":"Castle","details":"A medieval castle in northern Portugal linked to Afonso Henriques, the country's first king.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Guimar%C3%A3es1.jpg?width=1024"},{"name":"Gwalior Fort","rarity":"rare","id":"gwalior-fort","subtitle":"Fort","details":"A sandstone hill fortress in Madhya Pradesh, palaces and temples enclosed by walls above the city of Gwalior.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gwalior_Fort_front.jpg?width=1024"},{"name":"Gyeongbokgung","rarity":"rare","id":"gyeongbokgung","subtitle":"Palace","details":"Seoul's grandest Joseon palace, founded in 1395 behind the great Gwanghwamun gate and a lotus-pond pavilion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%EA%B4%91%ED%99%94%EB%AC%B8_%EC%9B%94%EB%8C%80.jpg?width=1024"},{"name":"Hever Castle","rarity":"rare","id":"hever-castle","subtitle":"Castle","details":"This moated Kent castle, built in 1270, was the childhood home of Anne Boleyn, second queen of Henry VIII.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hever_Castle_2014_06_20_1.jpg?width=1024"},{"name":"Hirosaki Castle","rarity":"rare","id":"hirosaki-castle","subtitle":"Castle","details":"A moated castle in Aomori famous for cherry blossoms around its three-storey keep and Edo-period gates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hirosaki-castle_Aomori_with_Sakura_blossoms.jpg?width=1024"},{"name":"Inveraray Castle","rarity":"rare","id":"inveraray-castle","subtitle":"Castle","details":"Seat of the Dukes of Argyll since the 18th century, Inveraray's green-towered facade overlooks Loch Fyne in Argyll.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inveraray_Castle_-_south-west_facade.jpg?width=1024"},{"name":"Jaisalmer Fort","rarity":"rare","id":"jaisalmer-fort","subtitle":"Fort","details":"A golden sandstone fort in the Thar Desert, still home to residents living and trading inside its 99 bastions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jaisalmer_forteresse.jpg?width=1024"},{"name":"Kamianets-Podilskyi Castle","rarity":"rare","id":"kamianets-podilskyi-castle","subtitle":"Castle","details":"Perched above the Smotrych River canyon in Ukraine, this many-towered fortress guarded the approaches to the historic town below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%97%D0%B8%D0%BC%D0%BE%D0%B2%D0%B0_%D1%84%D0%BE%D1%80%D1%82%D0%B5%D1%86%D1%8F.jpg?width=1024"},{"name":"Khotyn Fortress","rarity":"rare","id":"khotyn-fortress","subtitle":"Fortress","details":"This mighty Ukrainian fortress above the Dniester River was contested for centuries by Moldavian, Polish, Cossack and Ottoman forces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/73-250-0001_Khotyn_Fortress_RB_18.jpg?width=1024"},{"name":"Kilkenny Castle","rarity":"rare","id":"kilkenny-castle","subtitle":"Castle","details":"Built from 1195 by the Butler family on the River Nore, Kilkenny Castle anchored Norman power in south-east Ireland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kilkenny-castle.jpg?width=640"},{"name":"King Arthur and Tintagel","rarity":"rare","id":"king-arthur-and-tintagel","subtitle":"Legend","details":"Legend says King Arthur was conceived and born at Tintagel, whose ruined castle clings to Cornwall's rugged coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tintagel_-_Castle_-_King_Arthur_statue_-_geograph.org.uk_-_6981846.jpg?width=640"},{"name":"Książ Castle","rarity":"rare","id":"ksiaz-castle","subtitle":"Castle","details":"One of Poland's largest castles, this Silesian stronghold above a wooded gorge was home to the Hochberg family for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ksi%C4%85%C5%BC_2026_01.jpg?width=1024"},{"name":"Kumbhalgarh","rarity":"rare","id":"kumbhalgarh","subtitle":"Fort","details":"A Mewar hill fort in the Aravallis whose perimeter wall runs about 22 miles, among the longest in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kumbhalgarh_055.jpg?width=1024"},{"name":"Leeds Castle","rarity":"rare","id":"leeds-castle","subtitle":"Castle","details":"Set on islands in a lake in Kent, Leeds Castle was a royal palace for six medieval queens of England.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leeds_castle.JPG?width=1024"},{"name":"Machicolation","rarity":"rare","id":"machicolation","subtitle":"Castle Part","details":"A machicolation is an opening in a projecting parapet floor, used to drop stones or liquids on attackers at the wall base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Craigmillar_machicolations.jpg?width=1024"},{"name":"Marienberg Fortress","rarity":"rare","id":"marienberg-fortress","subtitle":"Fortress","details":"Overlooking Würzburg and the Main river, this fortress served for centuries as the seat of the city's prince-bishops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wurzburg_Marienberg_Fortress_on_the_Main_in_W%C3%BCrzburg.jpg?width=1024"},{"name":"Matsuyama Castle","rarity":"rare","id":"matsuyama-castle","subtitle":"Castle","details":"A hilltop castle in Ehime with one of Japan's twelve surviving original keeps, linked by turrets and heavy gates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matsuyama_castle%28Iyo%296.JPG?width=1024"},{"name":"Nagoya Castle","rarity":"rare","id":"nagoya-castle","subtitle":"Castle","details":"A flatland castle rebuilt with a concrete keep, first raised in the 1610s for the Owari branch of the Tokugawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nagoya_Castle_7.jpg?width=1024"},{"name":"Neuf-Brisach","rarity":"rare","id":"neuf-brisach","subtitle":"Fortress","details":"Vauban's last great work, an octagonal star-fort town raised on the Alsace plain near the Rhine from 1698.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Neuf-Brisach_%28view_from_the_southwest%29.jpg?width=1024"},{"name":"Nuremberg Castle","rarity":"rare","id":"nuremberg-castle","subtitle":"Castle","details":"This imperial castle above Nuremberg's old town hosted Holy Roman emperors and imperial diets throughout the Middle Ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nuernberg_Burg_Panorama_PtGUI.jpg?width=1024"},{"name":"Nymphenburg Palace","rarity":"rare","id":"nymphenburg-palace","subtitle":"Palace","details":"The Bavarian electors' summer palace in Munich, fronted by a broad canal and gardens laid out in French Baroque style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Nymphenburg_main_building.jpg?width=1024"},{"name":"Peleș Castle","rarity":"rare","id":"peles-castle","subtitle":"Palace","details":"Built for King Carol I of Romania in the Carpathians, this Neo-Renaissance palace-castle is famed for its carved wood interiors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/01_Chateau_Peles.jpg?width=1024"},{"name":"Peter and Paul Fortress","rarity":"rare","id":"peter-and-paul-fortress","subtitle":"Fortress","details":"Founded by Peter the Great in 1703 on an island in the Neva, this star fortress was the original citadel of St Petersburg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RUS-2016-Aerial-SPB-Peter_and_Paul_Fortress_02.jpg?width=1024"},{"name":"Pfalzgrafenstein Castle","rarity":"rare","id":"pfalzgrafenstein-castle","subtitle":"Castle","details":"A toll castle built on a rocky island in the Rhine in 1326, this ship-shaped stronghold taxed passing river traffic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Pfalzgrafenstein_2017.jpg?width=1024"},{"name":"Portcullis","rarity":"rare","id":"portcullis","subtitle":"Castle Part","details":"A portcullis is a heavy spiked grille of wood and iron that drops in grooves to bar a gateway, sometimes in pairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cahir_Castle_Portcullis_by_Kevin_King.jpg?width=1024"},{"name":"Real Felipe Fortress","rarity":"rare","id":"real-felipe-fortress","subtitle":"Fortress","details":"A great star-shaped fortress guarding the port of Callao in Peru, built by Spain to fend off pirates and privateers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Real_Felipe_Fortress.jpg?width=1024"},{"name":"Reichsburg Cochem","rarity":"rare","id":"reichsburg-cochem","subtitle":"Castle","details":"Rebuilt in Gothic Revival style in the 19th century, this castle towers over Cochem and the Moselle vineyards below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cochem%2C_Reichsburg%2C_2012-08_CN-01.jpg?width=1024"},{"name":"Rheinfels Castle","rarity":"rare","id":"rheinfels-castle","subtitle":"Castle","details":"Once the largest fortress on the Rhine, these extensive ruins above St. Goar include long tunnels, mines and casemates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Rheinfels_Bild_1.jpg?width=1024"},{"name":"Sanssouci","rarity":"rare","id":"sanssouci","subtitle":"Palace","details":"Frederick the Great's summer palace at Potsdam, a Rococo retreat of terraced vineyards built for music, philosophy and leisure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Sanssouci_2014.jpg?width=1024"},{"name":"Sforza Castle","rarity":"rare","id":"sforza-castle","subtitle":"Castle","details":"Milan's great red-brick fortress was rebuilt by Duke Francesco Sforza in the 15th century and later held works by Leonardo da Vinci.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20110725_Castello_Sforzesco_Milan_5557.jpg?width=1024"},{"name":"Shuri Castle","rarity":"rare","id":"shuri-castle","subtitle":"Castle","details":"Okinawa's Ryukyu royal palace castle in Naha, a red-lacquered hilltop complex rebuilt after wartime destruction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Naha_Okinawa_Japan_Shuri-Castle-01.jpg?width=1024"},{"name":"Siege of Acre","rarity":"rare","id":"siege-of-acre","subtitle":"Siege","details":"From 1189 to 1191 crusader armies besieged Acre, retaking the port city after two years of hunger, disease and assault.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/144990_acre_-_the_eastern_moat_PikiWiki_Israel.jpg?width=640"},{"name":"Siege of Rhodes","rarity":"rare","id":"siege-of-rhodes","subtitle":"Siege","details":"In 1522 Suleiman the Magnificent besieged Rhodes; after six months the Knights Hospitaller surrendered and left the island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fortifications_of_the_town_of_Rhodes_%289451535573%29.jpg?width=1024"},{"name":"Suomenlinna","rarity":"rare","id":"suomenlinna","subtitle":"Fortress","details":"Spread across islands off Helsinki, this sea fortress was built by Sweden in 1748 and is one of the largest maritime fortresses in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suomenlinna_aerial.JPG?width=1024"},{"name":"São Jorge Castle","rarity":"rare","id":"sao-jorge-castle","subtitle":"Castle","details":"A hilltop castle above Lisbon's old town, with Moorish-era walls, towers and views over the Tagus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_Sao_Jorge_Lisboa_1.JPG?width=1024"},{"name":"Tintagel Castle","rarity":"rare","id":"tintagel-castle","subtitle":"Castle","details":"Ruined on a wild Cornish headland, Tintagel's 13th-century castle is steeped in legends of King Arthur and Merlin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tintagel_Castle_-_May_2026.jpg?width=1024"},{"name":"Urquhart Castle","rarity":"rare","id":"urquhart-castle","subtitle":"Castle","details":"Overlooking Loch Ness, Urquhart's ruins date from the 13th century and witnessed centuries of clan conflict in the Highlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Urquhart_Castle_Tower_House_2.jpg?width=1024"},{"name":"Veste Coburg","rarity":"rare","id":"veste-coburg","subtitle":"Fortress","details":"One of Germany's largest surviving fortresses, Veste Coburg sheltered Martin Luther during the Diet of Augsburg in 1530.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_the_Coburg_Fortress.jpg?width=1024"},{"name":"Würzburg Residence","rarity":"rare","id":"wurzburg-residence","subtitle":"Palace","details":"A grand Baroque palace in Würzburg famed for its vast unsupported staircase vault and Tiepolo's enormous ceiling fresco.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Residencia%2C_Wurzburgo%2C_Alemania%2C_2025-10-03%2C_DD_104.jpg?width=1024"},{"name":"Akershus Fortress","rarity":"uncommon","id":"akershus-fortress","subtitle":"Fortress","details":"Built around 1300 to protect Oslo, this medieval castle turned Renaissance fortress still serves ceremonial and military roles in Norway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/14-09-02-oslo-RalfR-370.jpg?width=1024"},{"name":"Albrechtsburg Meissen","rarity":"uncommon","id":"albrechtsburg-meissen","subtitle":"Castle","details":"A late Gothic castle above Meissen, later home to Europe's first porcelain manufactory, founded there in 1710.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Albrechtsburg-2007.jpg?width=1024"},{"name":"Alcazaba of Málaga","rarity":"uncommon","id":"alcazaba-of-malaga","subtitle":"Fortress","details":"A Moorish hilltop fortress-palace in Málaga with double walls, arched gateways and garden courtyards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alcazaba_de_M%C3%A1laga_overview.jpg?width=1024"},{"name":"Aragonese Castle","rarity":"uncommon","id":"aragonese-castle","subtitle":"Castle","details":"This castle rises from a volcanic islet off Ischia, linked to the island by a stone causeway and crowned by Aragonese-era walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aragonese_Castle_Island_of_Ischia_%2853929679155%29.jpg?width=1024"},{"name":"Arrowslit","rarity":"uncommon","id":"arrowslit","subtitle":"Castle Part","details":"An arrowslit is a narrow vertical opening in a wall, splayed wide inside so an archer could shoot out while barely exposed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arrow_slat_corfe_castle.jpg?width=640"},{"name":"Bailey","rarity":"uncommon","id":"bailey","subtitle":"Castle Part","details":"The bailey was a castle's enclosed courtyard, holding stables, workshops, stores and lodgings inside the outer walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Krak_westliche_Ringmauern.jpg?width=1024"},{"name":"Balmoral Castle","rarity":"uncommon","id":"balmoral-castle","subtitle":"Palace","details":"Queen Victoria and Prince Albert built this Scots Baronial estate in Aberdeenshire in the 1850s as a royal Highland retreat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balmoral_Castle.jpg?width=1024"},{"name":"Battlements","rarity":"uncommon","id":"battlements","subtitle":"Castle Part","details":"Battlements are the tooth-like parapets atop a wall, giving defenders cover to shoot through gaps while staying protected.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Walls_of_Kumbhalgarh.jpg?width=1024"},{"name":"Belmonte Castle","rarity":"uncommon","id":"belmonte-castle","subtitle":"Castle","details":"A 15th-century hilltop castle in Cuenca with a triangular ward, star-shaped barbican and Mudéjar ceilings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_Belmonte%2C_Cuenca.jpg?width=1024"},{"name":"Bled Castle","rarity":"uncommon","id":"bled-castle","subtitle":"Castle","details":"Slovenia's oldest documented castle perches on a cliff high above Lake Bled, first mentioned in a deed of 1011.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Great_Bled_Castle.jpg?width=1024"},{"name":"Bojnice Castle","rarity":"uncommon","id":"bojnice-castle","subtitle":"Castle","details":"A romantic castle in Slovakia rebuilt in French Gothic style, standing over the spa town of Bojnice and its springs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice_%28Bojnitz%29_Castle_%28by_Pudelek%29.jpg?width=1024"},{"name":"Bourtange","rarity":"uncommon","id":"bourtange","subtitle":"Fort","details":"A Dutch star-fort village in Groningen, restored to its 1742 form with moats, bastions and a cobbled market square.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bourtange_vesting_9.JPG?width=1024"},{"name":"Bratislava Castle","rarity":"uncommon","id":"bratislava-castle","subtitle":"Castle","details":"With four corner towers above the Danube, Bratislava Castle was a border stronghold and a residence of Hungarian kings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bratislava_-_Burg_%28b%29.JPG?width=1024"},{"name":"Braunfels Castle","rarity":"uncommon","id":"braunfels-castle","subtitle":"Castle","details":"A picturesque castle of towers and half-timbering above the Lahn valley town of Braunfels in Hesse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Braunfels.jpg?width=1024"},{"name":"Bunratty Castle","rarity":"uncommon","id":"bunratty-castle","subtitle":"Castle","details":"Built in 1425 in County Clare, Bunratty is a great tower house of the MacNamara and O'Brien families on the Shannon estuary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunrattybig.jpg?width=1024"},{"name":"Byblos Castle","rarity":"uncommon","id":"byblos-castle","subtitle":"Castle","details":"A Crusader castle in Lebanon built partly from Roman columns, standing over the ancient port of Byblos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Byblos_Castle_2009.jpg?width=1024"},{"name":"Cahir Castle","rarity":"uncommon","id":"cahir-castle","subtitle":"Castle","details":"One of Ireland's largest castles, Cahir rises from a rocky island in the River Suir and dates mainly from the 13th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cahir_Castle%2C_Tipperary_County%2C_Ireland_%286961416840%29_%282%29.jpg?width=1024"},{"name":"Carlisle Castle","rarity":"uncommon","id":"carlisle-castle","subtitle":"Castle","details":"Built from 1093 to guard England's border city, Carlisle Castle endured more sieges than any other English fortress.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carlisle_Castle_-_Keep_-_geograph.org.uk_-_7823157.jpg?width=1024"},{"name":"Castel Nuovo","rarity":"uncommon","id":"castel-nuovo","subtitle":"Castle","details":"Naples' Maschio Angioino, built for Charles of Anjou in 1279, is crowned by five great round towers and a Renaissance triumphal-arch gate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castel_Nuovo%2C_N%C3%A1poles%2C_Italia%2C_2023-03-25%2C_DD_146.jpg?width=1024"},{"name":"Castelgrande","rarity":"uncommon","id":"castelgrande","subtitle":"Fortress","details":"The oldest and largest of Bellinzona's three castles, Castelgrande stands on a rocky hill fortified since Roman times.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelgrande_Bellinzona.JPG?width=1024"},{"name":"Castle Chapel","rarity":"uncommon","id":"castle-chapel","subtitle":"Castle Part","details":"Many castles kept a private chapel near the keep, so the lord's household could hear Mass without leaving the defences.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orford_Castle%2C_Chapel_on_the_upper_part_of_the_Lower_Hall_1_-_geograph.org.uk_-_5897082.jpg?width=1024"},{"name":"Castle of Manzanares el Real","rarity":"uncommon","id":"castle-of-manzanares-el-real","subtitle":"Castle","details":"A granite fortress-palace near Madrid built by the Mendoza family, set beside the Santillana reservoir.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_nuevo_de_Manzanares_el_Real_-_Manzanares_el_Real_01.jpg?width=1024"},{"name":"Castle Tower","rarity":"uncommon","id":"castle-tower","subtitle":"Castle Part","details":"Castle towers rose above the walls to command the ground, house guards and archers, and strengthen corners against attack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HallbarTower5.jpg?width=640"},{"name":"Changdeokgung","rarity":"uncommon","id":"changdeokgung","subtitle":"Palace","details":"A Joseon palace in Seoul laid out to fit its hilly ground, famed for its Secret Garden of pavilions and ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%EC%B0%BD%EB%8D%95%EA%B6%81_%EC%A0%84%EA%B2%BD_%282012%29.jpg?width=1024"},{"name":"Chepstow Castle","rarity":"uncommon","id":"chepstow-castle","subtitle":"Castle","details":"Begun in 1067 above the River Wye, Chepstow is the oldest surviving post-Roman stone fortification in Britain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chepstow_Castle_%284197%29.jpg?width=1024"},{"name":"Château d'Angers","rarity":"uncommon","id":"chateau-d-angers","subtitle":"Fortress","details":"A massive fortress in Angers ringed by 17 dark schist towers, home to the medieval Apocalypse Tapestry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_d%27Angers%2C_South_view_20170611_1.jpg?width=1024"},{"name":"Château d'Ussé","rarity":"uncommon","id":"chateau-d-usse","subtitle":"Castle","details":"A turreted Loire château at the edge of the Chinon forest, long associated with the Sleeping Beauty tale.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/07_CVL_-_Indre-et-Loire_-_Rigny-Uss%C3%A9_%282015-09-03_11-06-16%29.jpg?width=1024"},{"name":"Château de Blois","rarity":"uncommon","id":"chateau-de-blois","subtitle":"Palace","details":"A royal château in Blois whose wings span Gothic, Renaissance and Classical styles around one courtyard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Louis_XII_wing_of_the_castle_of_Blois_01.jpg?width=1024"},{"name":"Château de Chaumont","rarity":"uncommon","id":"chateau-de-chaumont","subtitle":"Castle","details":"A Loire château above Chaumont-sur-Loire once owned by Catherine de' Medici, later swapped with Diane de Poitiers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chateau_de_Chaumont%2C_2008.jpg?width=640"}]});
